window.TEXTP["76.16"] = [[["p","<b>Шейх аль-Альбани разъяснил этот вопрос в «аль-Аджуиба ан-нафи′а», стр. 115. </b>"],["sep",""],["h2","ГЛАВА № 2 — ОТКАЗ В ПЯТНИЦУ ОТ ЛЮБЫХ ДЕЛ"],["p","<b>См. «аль-Ихья», 1/169; «аль-Аджуиба ан-нафи′а», стр. 116. </b>"],["sep",""],["h2","ГЛАВА № 3 — УКРАШЕНИЕ СЕБЯ ДЛЯ ПЯТНИЦЫ ПУТЁМ СОВЕРШЕНИЯ НЕКОТОРЫХ ГРЕХОВ"],["p","<b>Например, некоторые люди в пятничный день бреют бороду, надевают шелковые одежды и золото. См. «аль-Аджуиба ан-нафи′а», стр. 116.</b>"],["sep",""],["c","ГЛАВА № 4 — НЕКОТОРЫЕ ЛЮДИ ЗАРАНЕЕ ПРИНОСЯТ КОВРИКИ В МЕЧЕТЬ В ПЯТНИЦУ ИЛИ В ДРУГОЙ ДЕНЬ ЕЩЕ ДО ТОГО, КАК САМИ РЕШАТ ОСТАТЬСЯ В МЕЧЕТИ"],["p","<b>См. «аль-Мадхаль», 2/124; «аль-Аджуиба ан-нафи′а», стр. 116. </b>"],["sep",""],["h2","ГЛАВА № 5 — ОСОБЫЕ ВИДЫ НАПОМИНАНИЯ В ПЯТНИЧНЫЙ ДЕНЬ<sup class=\"fn\">467</sup>"],["n",[[467,"Речь идёт об определенных поминаниях Аллаха или же нашидах (и тому подобное), которые люди стали произносить в пятницу, чтобы напомнить людям о том, что сегодня — пятница, хотя шариат установил для этого напоминания азан (призыв на пятничную молитву). Всё же прочее считается новшеством."]]],["p","<b>См. «аль-Мадхаль», 2/258-259; «аль-Ибда′ фи мадарр аль-ибтида′», стр. 67; «Маджаллят аль-Манар», 31/57; «аль-Аджуиба ан-нафи′а», стр. 116.</b>"],["sep",""],["h2","ГЛАВА № 6 — КОЛЛЕКТИВНЫЙ АЗАН В ПЯТНИЦУ"],["p","<b>См. «аль-Мадхаль», 2/208; «аль-Аджуиба ан-нафи′а», стр. 116.</b>"],["sep",""],["c","ГЛАВА № 7 — ДОПОЛНЕНИЕ КО ВТОРОМУ АЗАНУ В ПЯТНИЦУ, КОГДА НА ВТОРОЙ АЗАН ПРИВОДЯТ ВТОРОГО МУАЗЗИНА, КОТОРЫЙ СИДИТ НА СКАМЬЕ И ПОВТОРЯЕТ АЗАН ЗА ПЕРВЫМ МУАЗЗИНОМ"],["p","<b>См. «аль-Ибда′», стр. 75; «аль-Мадхаль», 2/208; «аль-Аджуиба ан-нафи′а», стр. 117.</b>"],["sep",""],["c","ГЛАВА № 8 — ПОСЛЕ ПЕРВОГО АЗАНА В ПЯТНИЦУ МУАЗЗИН ПОДНИМАЕТСЯ НА МИНАРЕТ, ЧТОБЫ ПРИЗВАТЬ ЖИТЕЛЕЙ СЕЛЕНИЯ ОТПРАВИТЬСЯ В МЕЧЕТЬ, ДАБЫ В МЕЧЕТИ СОБРАЛОСЬ СОРОК ЧЕЛОВЕК"],["p","<b>См. «Ислях аль-масаджид ′ан иль-бида′ уаль ′ауаид», стр. 69; «аль-Аджуиба ан-нафи′а», стр. 117.</b>"],["sep",""],["c","ГЛАВА № 9 — РАЗДАЧА КОРАНОВ, КОГДА ЛЮДИ СОБИРАЮТСЯ НА ПЯТНИЧНУЮ МОЛИТВУ, А ЗАТЕМ ВО ВРЕМЯ АЗАНА РАБОТНИК МЕЧЕТИ, КОТОРЫЙ РАЗДАЛ ИХ, ХОДИТ СРЕДИ ЛЮДЕЙ И СОБИРАЕТ ИХ"],["p","<b>См. «аль-Мадхаль», 2/223; «аль-Аджуиба ан-нафи′а», стр. 118. </b>"],["sep",""],["c","ГЛАВА № 10 — УБЕЖДЕНИЕ В ТОМ, ЧТО ПРАВЕДНЫМ ЛЮДЯМ РАЗРЕШЕНО ПЕРЕШАГИВАТЬ ЧЕРЕЗ ЛЮДЕЙ В ПЯТНИЦУ<sup class=\"fn\">468</sup>, ИБО ТЕ В ТАКОМ СЛУЧАЕ СМОГУТ БРАТЬ ОТ НИХ БЛАГОДАТЬ (БАРАКУ)"],["n",[[468,"Запрещено перешагивать через людей в пятничный день, чтобы добраться до первого ряда. Сообщается, что ‘Абдуллах ибн Буср (да будет доволен им Аллах) рассказывал: <i>«Однажды, когда пророк (да благословит его Аллах и приветствует) обращался (к людям) с проповедью в пятничный день, (в мечеть) явился некий мужчина и начал перешагивать через шеи людей. (Увидев его), пророк (да благословит его Аллах и приветствует) сказал: </i><b><i>″Сядь! Ты причинил неудобства (людям), (да еще) и опоздал″</i></b><i>». </i>Этот хадис передали Ахмад, Абу Дауд, ан-Насаи, а также Ибн Хузейма и Ибн Хиббан в своих «Сахихах»."]]]],[["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 118. </b>"],["sep",""],["h2","ГЛАВА № 11 — УБЕЖДЕНИЕ В ТОМ, ЧТО ЕСТЬ ДОПОЛНИТЕЛЬНЫЕ МОЛИТВЫ ПЕРЕД ПЯТНИЧНОЙ МОЛИТВОЙ, И СОВЕРШЕНИЕ ЭТИХ МОЛИТВ"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 118, и др. </b>"],["h2","ПОДРОБНОЕ РАЗЪЯСНЕНИЕ ДАННОГО ВОПРОСА"],["h3","<b>Сказал наш шейх аль-Альбани, да помилует его Всевышний Аллах, в «ас-Сахиха», 1/465: </b>"],["p","«Некоторые поздние ученые аргументировали этим хадисом<sup class=\"fn\">469</sup> в пользу узаконенности совершения дополнительной молитвы перед пятничной молитвой, но эта аргументация является ложной, ибо пришло в «Сахихе» аль-Бухари и в других книгах, что во времена пророка (да благословит его Аллах и приветствует) в пятничный день был только один азан и икама, а между ними была проповедь. Я разъяснил этот вопрос подробно в книге «аль-Аджуиба ан-нафи′а»."],["n",[[469,"Речь идёт о хадисе, в котором сказано: <b><i>«Перед каждой обязательной молитвой есть два ракаата (добровольной молитвы)». </i></b>См. «ас-Сахиха», 232."]]],["h3","<b>Также он сказал: </b>"],["p","«Все хадисы о том, что пророк (да благословит его Аллах и приветствует) совершал дополнительную молитву перед пятничной молитвой, являются недостоверными. Некоторые из них более слабые, чем другие, как это разъяснили аз-Зейля′и в «Насб ар-рая», 2/206-207, Ибн Хаджар в «аль-Фатх», 2/341, и др.»."],["p","<b>Также наш шейх, да помилует его Аллах, в «ад-Да′ифа», 3/45, передал слова аль-Бусайри из его книги «аз-Зауаид»: </b>"],["p","«Пророк (да благословит его Аллах и приветствует) не мог совершать молитву между азаном и икамой в пятничный день, ибо между ними была проповедь, а, значит, между ними не было молитвы. Да, когда ′Усман внёс второй азан (в пятницу), появилась возможность совершать дополнительную молитву до того, как имам выйдет на проповедь»."],["h3","<b>Затем шейх аль-Альбани сказал: </b>"],["p","«Однако не пришло, что период между азаном ′Усмана и проповедью — это время для совершения четырёх ракаатов дополнительной молитвы перед обязательной пятничной молитвой. И не пришло, что сподвижники совершали эту молитву во времена ′Усмана (да будет доволен им Аллах), значит, нет места этой аргументации. Даже если есть такое (свободное) время, это не означает, что разрешено вносить поклонение, которого не было во времена пророка (да благословит его Аллах и приветствует)»."],["h3","<b>Также сказал наш шейх, да помилует его Всевышний Аллах, в «аль-Аджуиба ан-нафи′а», стр. 46-50:</b>"],["p","«У этой дополнительной молитвы нет основы в достоверной Сунне и нет места для её совершения. Из предшествующих хадисов ты понял, что сначала наступает время молитвы, затем произносят азан, затем — проповедь, затем совершают молитву. Это — непрерывная цепочка. Всё это следует друг за другом. Где же время для совершения этой дополнительной молитвы?! Именно об этом говорит хафиз аль-′Иракы:"]],[["p","<i>«Не передано от пророка (да благословит его Аллах и приветствует), что он совершал молитву перед пятничной молитвой, ибо он приходил на пятничную молитву, и тут же произносили азан, а затем он обращался с проповедью». </i>"],["p","На это также обратили внимание некоторые ученые из числа ханафитов. Они сказали, что необходимо отправиться в мечеть и необходимо оставить торговлю в пятничный день уже после первого азана, то есть того азана, который произносится еще до того, как проповедник поднялся на минбар. И они сказали, что именно это мнение является правильным в их мазхабе, хотя они знали, что этого азана не было во времена пророка (да благословит его Аллах и приветствует), в те времена, когда был ниспослан аят: <b>«О те, которые уверовали! Когда призывают на молитву в пятничный день, то устремляйтесь к поминанию Аллаха и оставьте торговлю»</b><sup class=\"fn\">470</sup>. Этот аят был ниспослан об азане, который произносится тогда, когда проповедник поднимается на минбар, как мы уже говорили. Они знали обо всём этом, ибо всё это приходит в книгах Сунны, но им этого не хватило. Более того, они даже назвали слабым мнение ат-Тахауи, который был ханафитом, но выразил то мнение, которое соответствует Сунне. Он сказал: <i>«Азан, после которого нужно оставлять торговлю, это тот азан, который произносится, когда проповедник поднимается на минбар»</i><sup class=\"fn\">471</sup>. Но эти ханафиты сказали: <i>«Если бы в мечеть обязательно было бы отправляться после этого азана, то человек не успел бы совершить дополнительную молитву (перед обязательной пятничной)»</i><sup class=\"fn\">472</sup>."],["n",[[470,"Сура «аль-Джуму′а», аят 9."],[471,"То есть второй азан, а не первый."],[472,"См. «аль-Бахр ар-раик», 2/168; «аль-′Иная ′аля аль-Хидая», 1/421."]]],["p","Таким образом они признают, что эта дополнительная молитва (перед пятничной молитвой) не была известна во времена пророка (да благословит его Аллах и приветствует), и что сподвижники её не совершали, ведь у них не было времени, в которое они могли бы её совершить. Это является верным. Именно поэтому сказал Ибн уль-Каййим (да помилует его Аллах) в «Зад уль-ма′ад фи хадьи хайр иль-′ибад»:"],["p","<i>«А если кто-то думает, что сподвижники, когда Биляль произносил азан (на пятничную молитву), все вставали и совершали молитву в два ракаата, то он — самый невежественный человек в отношении Сунны». </i>"],["p","Но Аль-Камаль ибн уль-Хумам в «Фатх аль-Кадир», 1/422, привёл его слова по смыслу, не назвав при этом его имени, после чего сказал:"],["p","<i>«Ответ на это таков: пророк (да благословит его Аллах и приветствует) был вынужден приходить в мечеть уже после того, как солнце начинало двигаться в сторону заката</i><sup class=\"fn\">473</sup><i>. И, возможно, он совершал четыре ракаата дополнительной молитвы (после азана у себя дома). Мы обязаны вынести такое постановление, ибо существует такая вероятность. К тому же мы приводили в главе о дополнительных молитвах, что пророк (да благословит его Аллах и приветствует) обычно всегда совершал дополнительную молитву в четыре ракаата (после наступления времени обеденной молитвы) и говорил: </i><b><i>\"Это — период, когда открывают врата небес, и я хочу, чтобы в это время (на небеса) восходило моё праведное дело\". </i></b><i>И то же самое касается сподвижников». </i>"],["n",[[473,"То есть после того, как наступало время молитвы."]]]],[["p","Я скажу: это замечание не имеет никакой силы. Оно может быть опровергнуто с разных сторон."],["p","<b>Во-первых</b>, он строит свой вывод на том, что пророк (да благословит его Аллах и приветствует) был вынужден приходить в мечеть уже после того, как солнце начинало двигаться в сторону заката, но это не совсем так. Иногда он приходил в мечеть (на пятничную молитву) до того, как солнце начинало двигаться в сторону заката. Мы уже говорили об этом."],["p","<b>Во-вторых</b>, мы уже говорили о том, что пророк (да благословит его Аллах и приветствует) спешил подняться на минбар сразу после того, как солнце начинало движение. Где же то время, в которое он мог успеть совершить эту молитву?!"],["p","<b>В-третьих</b>, если бы пророк (да благословит его Аллах и приветствует) совершал четыре ракаата после того, как солнце начинало двигаться в сторону заката, но до азана, то это обязательно передали бы от него, особенно, если учесть, что это необычное явление — совершение дополнительной молитвы до азана. И также, если бы все сподвижники без исключения совершали бы эту дополнительную молитву одновременно в мечети. Если бы это имело место, это обязательно передали бы по многочисленным путям. А если ничего подобного не передано, значит, этого и не было."],["p","Сказал Абу Шама в своей книге «аль-Ба′ис ′аля инкар аль-бида′ уаль хауадис»:"],["p","<i>«Если ты скажешь: «Возможно, он совершал эту дополнительную молитву в своём доме после того, как солнце начинало двигаться в сторону заката, а уже потом выходил в мечеть», я скажу: если бы это имело место, то это передали бы его жены (да будет доволен ими Аллах), ведь они передавали известия обо всех остальных его молитвах, которые он совершал дома ночью и днём, и то, как именно он совершал эти молитвы. А если ничего такого не передано, значит, основа в том, что этого не было. Следовательно, это не является узаконенным». </i>"],["p","<b>В-четвертых</b>, он привёл хадис, посчитав, что он указывает на всеобщность, но если подумать над текстом этого хадиса, пришедшим в книгах Сунны, мы поймем, что это — ошибка. Эта дополнительная молитва касалась только обеденной молитвы (зухр)."],["p","Например, пришло в «Муватта Мухаммад», стр. 158: <i>«Обычно он совершал четыре ракаата перед обеденной молитвой (зухр) после того, как солнце начинало двигаться в сторону заката». </i>"],["p","И именно так этот хадис передал аз-Зейля′и в «Насб ар-рая», 2/142. Получается, что этот хадис связан именно с обеденной молитвой (зухр). Есть еще более очевидный хадис со слов ′Абдуллаха ибн ус-Саиба: <i>«Обычно посланник Аллаха (да благословит его Аллах и приветствует) совершал четыре ракаата после того, как солнце начинало двигаться в сторону заката, но перед обеденной молитвой (зухр). И он сказал: </i><b><i>\"В этот час открываются врата небес, и я хочу, чтобы в это время (на небеса) восходило моё праведное дело\"». </i></b>Передали Ахмад, 3/411, ат-Тирмизи, 2/343. Ат-Тирмизи назвал хадис хорошим. Его цепочка передатчиков является достоверной в соответствии с условиями Муслима."]],[["p","Посмотри, в этом хадисе сказано: <i>«…перед обеденной молитвой (зухр)…», </i>а до этого сказано: <i>«…после того, как солнце начинало двигаться в сторону заката (заваль)…»</i><sup class=\"fn\">474</sup>. Каждый знает, что «заваль» наступает до обеденной молитвы (зухр). Передатчик произнёс слова <i>«…перед обеденной молитвой (зухр)…», </i>чтобы исключить пятничную молитву из слов <i>«…после того, как солнце начинало двигаться в сторону заката (заваль)…». </i>"],["n",[[474,"Движение солнца в сторону заката в полдень в религиозной терминологии именуют термином «заваль». Когда наступает «заваль», наступает и время обеденной молитвы (зухр)."]]],["h3","<b>Затем шейх сказал на стр. 54-56:</b>"],["p","«<b>В-шестых, </b>передал аль-Бухари, 1/394, что Ибн ′Умар сказал: <i>«Я совершал вместе с посланником Аллаха (да благословит его Аллах и приветствует) два ракаата до обеденной молитвы (зухр), два ракаата после обеденной молитвы (зухр), два ракаата после пятничной молитвы, два ракаата после вечерней молитвы (магриб) и два ракаата после ночной молитвы (′иша)». </i>"],["p","Также передал Муслим, 2/726, и добавил: <i>«Что касается вечерней (магриб), ночной (′иша) и пятничной молитвы, то я совершал (два ракаата после них) вместе с пророком (да благословит его Аллах и приветствует) в его доме». </i>"],["p","Этот хадис ясно указывает на то, что пророк (да благословит его Аллах и приветствует) не совершал дополнительных молитв перед пятничной молитвой: ни дома, ни в мечети. Если бы он совершал что-то такое, Ибн ′Умар (да будет доволен им Аллах) обязательно передал бы это нам, как он передал нам известия о других дополнительных молитвах. И здесь он упомянул дополнительную молитву перед обеденной молитвой (зухр), но не перед пятничной, а это — один из самых сильных доводов на то, что до пятничной молитвы нет дополнительных молитв."],["p","<b>Никто из имамов не говорил о том, что перед пятничной молитвой есть дополнительные молитвы.</b>"],["p","Из вышесказанного мы понимаем, что в хадисе Абу Аюба нет указания на желательность совершения четырех ракаатов после «заваля» перед пятничной молитвой."],["p","«Именно поэтому большинство имамов было единогласно в том, что перед пятничной молитвой нет дополнительной молитвы, связанной с ней по времени и определенной конкретным количеством ракаатов. Эту молитву можно было утвердить только из слов пророка (да благословит его Аллах и приветствует) и его действий, но он не установил ничего подобного ни словами, ни поступками. Таково мнение Малика и аш-Шафи′и, а также большинства шафиитов. И это известное мнение в мазхабе Ахмада»<sup class=\"fn\">475</sup>."],["n",[[475,"Слова шейха ислама Абу-ль ′Аббаса Ибн Теймии в «аль-Фатауа», 1/136. Также см. «Маджму′а ар-расаиль аль-кубра», 2/167-168."]]]],[["p","И сказал аль-′Иракы: <i>«И я не видел, чтобы три имама побуждали совершать дополнительную молитву перед пятничной». </i>"],["p","<b>Затем наш шейх, да помилует его Всевышний Аллах, передал слова Абу Шамы из его книги «аль-Ба′ис ′аля инкар аль-бида′ уаль хауадис», стр. 70:</b>"],["p","«Пророк (да благословит его Аллах и приветствует) в пятницу выходил из дома, поднимался на минбар, а затем муаззин произносил азан, и когда он заканчивал, пророк (да благословит его Аллах и приветствует) начинал проповедь. И если бы у пятничной молитвы была дополнительная молитва перед ней, то пророк (да благословит его Аллах и приветствует) повелел бы им совершать эту молитву после азана, и сам совершал бы её. И во времена пророка (да благословит его Аллах и приветствует) не было другого азана. И этого придерживаются маликиты до наших дней»."],["h3","<b>Затем наш шейх, да помилует его Всевышний Аллах, сказал на стр. 63-69:</b>"],["p","«На то, что нет дополнительной молитвы перед пятничной, также указывают слова пророка (да благословит его Аллах и приветствует): <b><i>«Когда кто-нибудь из вас совершит пятничную молитву, пусть совершит после неё четыре ракаата (дополнительной молитвы)»</i></b><sup class=\"fn\">476</sup>."],["n",[[476,"Передал Муслим и другие."]]],["p","Если бы до пятничной молитвы была дополнительная молитва, то пророк (да благословит его Аллах и приветствует) обязательно упомянул бы её в этом хадисе, где он упомянул дополнительную молитву, совершаемую после. Ведь именно здесь надлежащее место для её упоминания."],["p","Таким образом, когда человек входит в мечеть в пятницу, ему желательно перед тем, как он сядет, совершить дополнительные молитвы, но эти молитвы не связаны с пятничной молитвой и не ограничены конкретным количеством ракаатов. Он может совершать их, пока не появится имам. Что же касается того, что после первого азана люди встают и совершают молитву в четыре ракаата, то этому нет основы в Сунне. Напротив, это является новшеством, а суждение религии о новшествах известно."],["p","Кто-то может подумать, что эта молитва была известна во времена правления ′Усмана, и он повелел произносить первый азан (до основного азана), чтобы люди получили возможность совершить дополнительную молитву перед пятничной. Вообще, на подобное утверждение нет никакого довода. Это — простое предположение, а предположение ничем не помогает человеку в поиске истины. То есть это не передано в хадисах, но к тому же в хадисе ас-Саиба есть то, что указывает на то, что это маловероятно. В нём сказано, что первый азан произносился на рынке, а дополнительная молитва не совершается на рынке. Она совершается в мечети. Но те люди, которые находились в мечети, не слышали азан с рынка, и поэтому не могли совершать эту дополнительную молитву."]],[["p","Затем Хишам перенёс этот азан к дверям мечети, а пророческий азан уже произносился внутри мечети, как мы уже говорили. Но не передано, чтобы они совершали какую-то молитву между двумя этими азанами, но даже если бы они совершали такую молитву, в этом не было бы довода, так как эпоха сподвижников уже закончилась. То, что не было религией тогда, не станет религией и сегодня. И последние поколения этой общины исправятся только лишь посредством того, посредством чего исправились первые поколения, как сказал имам Малик, да помилует его Всевышний Аллах."],["p","Именно поэтому сказал Ибн уль-Хаджж в «аль-Мадхаль», 2/239:"],["p","<i>«Нужно запрещать людям то, что они внесли из новшеств, а именно совершение молитвы после первого азана на пятничную молитву, ибо это противоречит тому, чего придерживались предшественники (да будет доволен ими Аллах). Они делились на две группы: некоторые из них совершали дополнительную молитву, когда входили в мечеть и до тех пор, пока имам не поднимался на минбар, а когда имам садился на минбаре, они прекращали свои молитвы; а некоторые из них совершали дополнительную молитву, а затем садились и сидели вплоть до пятничной молитвы. То есть не совершали дополнительных молитв ни после первого азана, ни после второго. И тот, кто совершал дополнительные молитвы, не порицал сидящего, а сидящий не порицал того, кто совершал дополнительные молитвы. Это противоречит тому, что люди делают сегодня: они сидят, а после азана встают на дополнительную молитву</i><sup class=\"fn\">477</sup>."],["n",[[477,"Здесь в сносках шейх аль-Альбани добавил: «А сегодня всё обстоит иначе. Люди порицают того, кто остаётся сидеть, считая, что он оставил сунну, хотя сунна с ними, а не с ними»."]]],["p","<i>Кто-то может сказать: «Но ведь в это время разрешено молиться. Передал имам аль-Бухари со слов ′Абдуллаха ибн Мугаффаля (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Между двумя азанами — молитва\", </i></b><i>повторив это трижды, и на третий раз добавив: </i><b><i>\"…для того, кто пожелает…\"». </i></b><i>Ответ: предшественники (да будет доволен ими Аллах) лучше разбирались в вопросах религии и лучше знали хадисы, и нам остаётся только следовать за ними в том, что они делали». </i>"],["p","Я скажу: этого ответа недостаточно и он не избавляет от непониманий, ибо из этого ответа понимается, что он согласен с тем, что хадис указывает на узаконенность намеренного совершения молитвы между азаном ′Усмана и пророческим азаном, но это не так. Значит, нужно подробнее разъяснить этот момент."],["p","Я скажу: этот хадис ни в коем случае не указывает на это, ибо слова «между двумя азанами» означают между азаном и икамой. В этом единогласны все ученые. И если дело обстоит так, значит, этот хадис не годится в качестве довода на то, о чём говорил выше сторонник этой аргументации."]],[["p","Затем мы можем представить, что этот хадис, на самом деле, следует понимать в буквальном смысле, и что он, на самом деле, включает в себя и азан ′Усмана, хотя все ученые единогласны в том, что этого азана не было во времена пророка (да благословит его Аллах и приветствует). Но даже если бы мы согласились с этим, то этот хадис указывал бы совершение молитвы, которая ни с чем не связана и не ограничена каким-то количеством ракаатов. Мы сейчас разбираем не этот вопрос. Мы сейчас говорим о том, что они утверждают, что эта дополнительная молитва является крайне желательной и относится к молитвам «раватиб», и что её нужно совершать в четыре ракаата, а этот хадис вообще никак не может указывать на это. И также на это не указывают никакие другие хадисы."],["p","Также на это указывает то, что никто из ученых не аргументировал этим хадисом, когда говорил о желательности конкретной молитвы с конкретным количеством ракаатов между двумя азанами. А, особенно, возьми азан на вечернюю молитву (магриб) и икаму. Максимум, что они говорили, так это то, что этот хадис просто указывает на желательность молитвы, которая не ограничена каким-то количеством ракаатов. И это очевидно для того, кто беспристрастен»."],["h3","<b>Затем шейх, да помилует его Всевышний Аллах, сказал на стр. 69-70:</b>"],["p","«Вкратце подведем итог всего вышеприведенного исследования."],["p","Установлено в Сунне, а также из деяний сподвижников, что перед азаном и перед наступлением времени пятничной молитвы желательно совершать дополнительную молитву, но она не связана с каким-то конкретным временем и не ограничена каким-то количеством ракаатов. И если ты хочешь следовать за кем-то, то следуй за ними, ведь, поистине, лучший путь — это путь Мухаммада, а худшие из дел — это те, что были внесены в религию, и всё, что было внесено в религию, является новшеством, и каждое новшество — заблуждение, а каждое заблуждение — в Огне»."],["h3","<b>Затем наш шейх, да помилует его Всевышний Аллах, сказал на стр. 71:</b>"],["p","«<b>В-пятых</b>, если человек вошёл в мечеть перед азаном, он совершает дополнительную молитву, столько ракаатов, сколько пожелает."],["p","<b>В-шестых</b>, что касается намеренного совершения дополнительной молитвы между первым и вторым азаном (они называют её «дополнительная молитва, совершаемая перед пятничной»), то этому нет основы в Сунне, и об этом не говорил никто из сподвижников и имамов»."],["sep",""],["h2","ГЛАВА № 12 — УСТЛАНИЕ СТУПЕНЕЙ МИНБАРА КОВРАМИ В ПЯТНИЧНЫЙ ДЕНЬ"],["p","<b>См. «аль-Мадхаль», 2/166; «аль-Аджуиба ан-нафи′а», стр. 118. </b>"],["sep",""],["h2","ГЛАВА № 13 — УСТАНОВЛЕНИЕ ЧЕРНЫХ ФЛАГОВ НАД МИНБАРОМ ВО ВРЕМЯ ПРОПОВЕДИ"]],[["p","<b>См. «аль-Мадхаль», 2/166; «аль-Аджуиба ан-нафи′а», стр. 119. </b>"],["sep",""],["h2","ГЛАВА № 14 — ЗАНАВЕСКИ ДЛЯ МИНБАРА"],["p","<b>См. «ас-Сунан», 53; «аль-Аджуиба ан-нафи′а», стр. 119.</b>"],["sep",""],["h2","ГЛАВА № 15 — ПОСТОЯННОЕ НОШЕНИЕ ЧЕРНОЙ ОДЕЖДЫ ИМАМОМ В ПЯТНИЦУ"],["p","<b>См. «аль-Ихья», 1/162, 165; «аль-Мадхаль», 2/266; «Шарх шир′ат аль-ислям», стр. 140; «аль-Аджуиба ан-нафи′а», стр. 119.</b>"],["sep",""],["h2","ГЛАВА № 16 — НОШЕНИЕ ЧАЛМЫ ИМЕННО НА ПЯТНИЧНУЮ МОЛИТВУ ИЛИ НА КАКИЕ-ТО ДРУГИЕ МОЛИТВЫ<sup class=\"fn\">478</sup>"],["n",[[478,"Здесь в сносках шейх аль-Альбани добавил: «Что касается хадисов, говорящих о достоинстве ношения чалмы на молитву, то они не являются достоверными, как я разъяснил это в «ад-Да′ифа», № 127»."]]],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 119.</b>"],["sep",""],["h2","ГЛАВА № 17 — НАДЕВАНИЕ ХУФФОВ (КОЖАНЫХ НОСКОВ) ИМЕННО НА ПРОПОВЕДЬ И НА ПЯТНИЧНУЮ МОЛИТВУ"],["p","<b>См. «аль-Мадхаль», 2/166; «аль-Аджуиба ан-нафи′а», стр. 119.</b>"],["sep",""],["h2","ГЛАВА № 18 — ЧТЕНИЕ АЯТА: «ВОИСТИНУ, АЛЛАХ И ЕГО АНГЕЛЫ БЛАГОСЛОВЛЯЮТ ПРОРОКА»<sup class=\"fn\">479</sup>"],["n",[[479,"Сура «аль-Ахзаб», аят 56."]]],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 119.</b>"],["sep",""],["c","ГЛАВА № 19 — КОГДА ПРОИЗНОСЯЩИЙ ПРОПОВЕДЬ (ХАТЫ́Б)<sup class=\"fn\">480</sup> ПОЯВЛЯЕТСЯ В МЕЧЕТИ И ДО ТЕХ ПОР, ПОКА ОН НЕ ДОЙДЕТ ДО МИНБАРА, МУАЗЗИН ЧИТАЕТ ХАДИС: «ЕСЛИ ТЫ СКАЖЕШЬ СВОЕМУ ТОВАРИЩУ…»."],["n",[[480,"Здесь и далее под словом «хаты́б» имеется в виду того, кто будет произносить пятничную проповедь."]]],["p","<b>См. «аль-Мадхаль», 2/166; «Шарх ат-тарика аль-Мухаммадия», 1/114, 115, 4/323; «аль-Манар», 5/951, 19/541; «аль-Ибда′», 75; «ас-Сунан», 24; «аль-Аджуиба ан-нафи′а», стр. 119.</b>"],["sep",""],["h2","ГЛАВА № 20 — УСТАНОВЛЕНИЕ МИНБАРА, У КОТОРОГО БОЛЬШЕ ТРЁХ СТУПЕНЕК<sup class=\"fn\">481</sup>"],["n",[[481,"Этот вопрос был разъяснен в 9-ой главе предыдущего раздела."]]],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 120; «Сыфат ас-салят», стр. 81; «ас-Самар аль-мустатаб», 1/413-414. </b>"],["sep",""],["h2","ГЛАВА № 21 — ХАТЫ́Б ОСТАНАВЛИВАЕТСЯ ПЕРЕД МИНБАРОМ И НАЧИНАЕТ ОБРАЩАТЬСЯ К АЛЛАХУ С МОЛЬБАМИ"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 120. </b>"],["sep",""],["h2","ГЛАВА № 22 — ХАТЫ́Б ДЕЛАЕТ ПАУЗУ ПЕРЕД ТЕМ, КАК ВСТАТЬ НА ПРОПОВЕДЬ"],["p","<b>См. «аль-Ба′ис», 64; «аль-Аджуиба ан-нафи′а», стр. 121. </b>"],["h3","<b>Сказал аль-Касими, да помилует его Аллах, в «Ислях аль-масаджид», стр. 65:</b>"],["p","«После произнесения азана произносящий проповедь делает небольшую паузу, а затем встаёт и произносит проповедь»."],["h3","<b>Сказал шейх аль-Альбани, да помилует его Аллах, в примечаниях к книге «Ислях аль-масаджид», стр. 65: </b>"],["p","«Эта пауза не имеет никакого отношения к Сунне. Обрати же на это внимание!»."],["sep",""],["c","ГЛАВА № 23 — КОГДА ХАТЫ́Б ПОДНИМАЕТСЯ НА МИНБАР (ИЛИ ПЕРЕД ЭТИМ), ЛЮДИ ДЕКЛАМИРУЮТ СТИХОТВОРЕНИЯ, ВОСХВАЛЯЮЩИЕ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)"],["p","<b>См. «аль-Манар», 31/474; «аль-Аджуиба ан-нафи′а», стр. 121.</b>"],["sep",""],["h2","ГЛАВА № 24 — КОГДА ХАТЫ́Б ПОДНИМАЕТСЯ НА МИНБАР, ОН СВОИМ ПОСОХОМ СТУЧИТ ПО СТУПЕНЬКАМ МИНБАРА"]],[["p","<b>См. «аль-Ба′ис», 64; «аль-Мадхаль», 2/267; «Ислях аль-масаджид», 50; «аль-Манар», 18/558; «аль-Аджуиба ан-нафи′а», стр. 121.</b>"],["sep",""],["c","ГЛАВА № 25 — КАЖДЫЙ РАЗ, КАК ХАТЫ́Б СТУЧИТ ПО МИНБАРУ, МУАЗЗИНЫ ПРИЗЫВАЮТ БЛАГОСЛОВЕНИЕ НА ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)"],["p","<b>См. «аль-Мадхаль», 2/250, 267; «аль-Аджуиба ан-нафи′а», стр. 121.</b>"],["sep",""],["c","ГЛАВА № 26 — ГЛАВНЫЙ МУАЗЗИН ПОДНИМАЕТСЯ НА МИНБАР ВМЕСТЕ С ХАТЫ́Б, НО САДИТСЯ НИЖЕ НЕГО И ГОВОРИТ: «АМИН! О АЛЛАХ! АМИН! ПУСТЬ АЛЛАХ ПРОСТИТ ТОГО, КТО ГОВОРИТ: «АМИН!» И Т. Д."],["p","<b>См. «аль-Мадхаль», 2/268; «аль-Аджуиба ан-нафи′а», стр. 121.</b>"],["sep",""],["c","ГЛАВА № 27 — КОГДА ХАТЫ́Б ПОДНИМАЕТСЯ НА МИНБАР, ОН НЕ ПОВОРАЧИВАЕТСЯ К ЛЮДЯМ И НЕ ДАЁТ ИМ САЛЯМ, А ПОВОРАЧИВАЕТСЯ В СТОРОНУ КААБЫ И НАЧИНАЕТ ВЗЫВАТЬ К АЛЛАХУ<sup class=\"fn\">482</sup>"],["n",[[482,"Сказал шейх ислама Ибн Теймия в «аль-Ихтиярат», 48: «Имам поднимается на минбар и начинает взывать к Аллаху — этому нет основы (в религии)»."]]],["p","<b>См. «аль-Ба′ис», 64; «аль-Мадхаль», 2/267; «Ислях аль-масаджид», 50; «аль-Манар», 18/558; «аль-Аджуиба ан-нафи′а», стр. 121.</b>"],["sep",""],["h2","ГЛАВА № 28 — КОГДА ХАТЫ́Б ВЫХОДИТ К ЛЮДЯМ, ОН НЕ ДАЁТ ИМ САЛЯМ"],["p","<b>См. «аль-Мадхаль», 22/166; «аль-Аджуиба ан-нафи′а», стр. 122.</b>"],["sep",""],["h2","ГЛАВА № 29 — ПРОИЗНЕСЕНИЕ ВТОРОГО АЗАНА ВНУТРИ МЕЧЕТИ ПРЯМ ВОЗЛЕ ХАТЫ́БА"],["p","<b>См. «аль-И′тисам», 2/207-208; «аль-Манар», 19/540; «аль-Аджуиба ан-нафи′а», 28-31. </b>"],["p","<b>Сказал шейх аль-Альбани, да помилует его Аллах, в примечаниях к книге «Ислях аль-масаджид», стр. 132:</b>"],["p","«Это также является новшеством. Во времена пророка (да благословит его Аллах и приветствует) азан произносили над мечетью, и произносился только один азан, как я разъяснил это в книге «аль-Аджуиба ан-нафи′а»."],["sep",""],["c","ГЛАВА № 30 — В НЕКОТОРЫХ МЕЧЕТЯХ БЫВАЕТ ДВУХ МУАЗЗИНА: ОДИН ВСТАЕТ ПЕРЕД МИНБАРОМ, А ВТОРОЙ — НА МИНБАРЕ. ПЕРВЫЙ МУАЗЗИН ПРОИЗНОСИТ СЛОВА АЗАНА ШЕПОТОМ, А ВТОРОЙ ПОВТОРЯЕТ ИХ ГРОМКИМ ГОЛОСОМ"],["p","<b>См. «Ислях аль-масаджид мин аль-бида′ уаль ′ауаид», 143; «аль-Аджуиба ан-нафи′а», стр. 123. </b>"],["sep",""],["p","ГЛАВА № 31 — КОГДА ХАТЫ́Б НАЧИНАЕТ ПРОПОВЕДЬ, ГЛАВНЫЙ МУАЗЗИН ГОВОРИТ ЛЮДЯМ: «О ЛЮДИ! ДОСТОВЕРНО ПЕРЕДАНО, ЧТО ПОСЛАННИК АЛЛАХА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) СКАЗАЛ: <i>«ЕСЛИ В ПЯТНИЧНЫЙ ДЕНЬ ВО ВРЕМЯ ПРОПОВЕДИ ТЫ СКАЖЕШЬ СВОЕМУ ТОВАРИЩУ: «ЗАМОЛЧИ», ТО ТЫ ПРОИЗНЕСЕШЬ ПУСТЫЕ СЛОВА».</i> ПОЭТОМУ МОЛЧИТЕ (ВО ВРЕМЯ ПРОПОВЕДИ), ДА ПОМИЛУЕТ ВАС АЛЛАХ!»."],["p","<b>См. «аль-Мадхаль», 2/268; «ас-Сунан уаль мубтада′ат», 24; «аль-Аджуиба ан-нафи′а», стр. 122. </b>"],["sep",""],["c","ГЛАВА № 32 — КОГДА ХАТЫ́Б ЗАКАНЧИВАЕТ ПЕРВУЮ ПРОПОВЕДЬ И САДИТСЯ, МУАЗЗИН ГОВОРИТ: «ПУСТЬ АЛЛАХ ПРОСТИТ ТЕБЯ И ТВОИХ РОДИТЕЛЕЙ, И НАС, И НАШИХ РОДИТЕЛЕЙ, И ВСЕХ ПРИСУТСТВУЮЩИХ»."],["p","<b>См. «Фатауа Ибн Теймия», 1/129; «Ислях аль-масаджид», 75-76; «аль-Аджуиба ан-нафи′а», стр. 123.</b>"],["sep",""],["h2","ГЛАВА № 33 — ВО ВРЕМЯ ПЯТНИЧНОЙ ПРОПОВЕДИ ХАТЫ́Б ОПИРАЕТСЯ НА МЕЧ"]],[["p","<b>См. «ас-Сунан уаль мубтада′ат», 55; «аль-Аджуиба ан-нафи′а», стр. 123.</b>"],["sep",""],["c","ГЛАВА № 34 — НЕКОТОРЫЕ ЛЮДИ НАМЕРЕННО САДЯТСЯ ВОЗЛЕ МИНБАРА ВО ВРЕМЯ ПЯТНИЧНОЙ ПРОПОВЕДИ, СЧИТАЯ, ЧТО ЭТО СПОСОБСТВУЕТ ИСЦЕЛЕНИЮ ОТ БОЛЕЗНЕЙ"],["p","<b>См. «аль-Манар», 7/501-503; «аль-Аджуиба ан-нафи′а», стр. 123.</b>"],["sep",""],["p","ГЛАВА № 35 — НЕКОТОРЫЕ ХАТЫ́БЫ ОТКАЗЫВАЮТСЯ ОТ ПРОИЗНЕСЕНИЯ ВСТУПЛЕНИЯ, КОТОРОЕ ПРОИЗНОСИЛ ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ): «ПОИСТИНЕ, ВСЯ ХВАЛА АЛЛАХУ, КОТОРОГО МЫ ВОСХВАЛЯЕМ, ПРОСИМ О ПОМОЩИ И ПРОЩЕНИИ», А ТАКЖЕ ОТ СЛОВ, КОТОРЫЕ ПРОИЗНОСИЛ ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ): «А ЗАТЕМ: ПОИСТИНЕ, ЛУЧШАЯ РЕЧЬ — ЭТО РЕЧЬ АЛЛАХА»"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 123.</b>"],["sep",""],["c","ГЛАВА № 36 — НЕКОТОРЫЕ ХАТЫ́БЫ ОТКАЗЫВАЮТСЯ ОТ НАПОМИНАНИЯ ЛЮДЯМ ВО ВРЕМЯ СВОИХ ПРОПОВЕДЕЙ ПУТЕМ ЧТЕНИЯ СУРЫ «КАФ» (№ 50), ХОТЯ ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) ПОСТОЯННО ПОСТУПАЛ ТАК"],["p","<b>См. «ас-Сунан», 57; «аль-Аджуиба ан-нафи′а», стр. 124.</b>"],["sep",""],["c","ГЛАВА № 37 — НЕКОТОРЫЕ ХАТЫ́БЫ В ПЯТНИЧНЫЙ ДЕНЬ В КОНЦЕ ПРОПОВЕДИ ПОСТОЯННО ЧИТАЮТ ХАДИС: «ТОТ, КТО ПОКАЯЛСЯ В ГРЕХЕ, ПОДОБЕН ТОМУ, КТО ВОВСЕ ЕГО НЕ СОВЕРШАЛ»."],["p","<b>См. «ас-Сунан», 56; «аль-Аджуиба ан-нафи′а», стр. 124.</b>"],["sep",""],["h2","ГЛАВА № 38 — НЕКОТОРЫЕ ХАТЫ́БЫ В НАШИ ДНИ ПОСЛЕ ОКОНЧАНИЯ ПЕРВОЙ ПРОПОВЕДИ ОБРАЩАЮТСЯ К ЛЮДЯМ С САЛЯМОМ"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 124.</b>"],["sep",""],["h2","ГЛАВА № 39 — КОГДА ХАТЫ́Б САДИТСЯ МЕЖДУ ДВУМЯ ПРОПОВЕДЯМИ, ЛЮДИ ТРИЖДЫ ЧИТАЮТ СУРУ «АЛЬ-ИХЛЯС» (№ 112)"],["p","<b>См. «ас-Сунан», 56; «аль-Аджуиба ан-нафи′а», стр. 124.</b>"],["sep",""],["h2","ГЛАВА № 40 — НЕКОТОРЫЕ ПРИСУТСТВУЮЩИЕ ВО ВРЕМЯ ВТОРОЙ ПРОПОВЕДИ ВСТАЮТ И СОВЕРШАЮТ МОЛИТВУ ПРИВЕТСТВИЯ МЕЧЕТИ"],["p","<b>См. «аль-Манар», 18/559; «ас-Сунан», 51; «аль-Аджуиба ан-нафи′а», стр. 124.</b>"],["sep",""],["h2","ГЛАВА № 41 — КОГДА ХАТЫ́Б САДИТСЯ МЕЖДУ ДВУМЯ ПРОПОВЕДЯМИ, ЛЮДИ ПОДНИМАЮТ РУКИ И НАЧИНАЮТ ВЗЫВАТЬ К АЛЛАХУ"],["p","<b>См. «аль-Манар», 6/793-794, 18/559; «аль-Аджуиба ан-нафи′а», стр. 124.</b>"],["sep",""],["h2","ГЛАВА № 42 — ВО ВРЕМЯ ВТОРОЙ ПРОПОВЕДИ ХАТЫ́Б СПУСКАЕТСЯ НА НИЖНЮЮ СТУПЕНЬКУ МИНБАРА, А ЗАТЕМ ВНОВЬ ПОДНИМАЕТСЯ ОБРАТНО"],["p","<b>См. «Хашия Ибн ′Абидин», 1/770; «аль-Аджуиба ан-нафи′а», стр. 124.</b>"],["sep",""],["h2","ГЛАВА № 43 — НЕКОТОРЫЕ ХАТЫ́БЫ СЛИШКОМ БЫСТРО ПРОИЗНОСЯТ ВТОРУЮ ПРОПОВЕДЬ"],["p","<b>См. «аль-Манар», 18/558; «аль-Аджуиба ан-нафи′а», стр. 125.</b>"],["sep",""],["c","ГЛАВА № 44 — ХАТЫ́Б ПОВОРАЧИВАЕТСЯ НАПРАВО И НАЛЕВО, КОГДА ГОВОРИТ: «Я ПОВЕЛЕВАЮ ВАМ!», «Я ЗАПРЕЩАЮ ВАМ!», А ТАКЖЕ ВО ВРЕМЯ ПРИЗЫВА БЛАГОСЛОВЕНИЯ НА ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)"],["p","<b>См. «аль-Ба′ис», 65; «Хашия Ибн ′Абидин», 1/759; «Ислях аль-масаджид», 50; «аль-Манар», 18/558; «аль-Аджуиба ан-нафи′а», стр. 125.</b>"],["sep",""],["c","ГЛАВА № 45 — ХАТЫ́Б ПОДНИМАЕТСЯ НА СТУПЕНЬ МИНБАРА, КОГДА ПРОСИТ БЛАГОСЛОВЕНИЯ ДЛЯ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), А КОГДА ЗАКАНЧИВАЕТ, СПУСКАЕТСЯ ОБРАТНО"]],[["p","<b>См. «аль-Ба′ис», 65; «аль-Аджуиба ан-нафи′а», стр. 125.</b>"],["sep",""],["c","ГЛАВА № 46 — НЕКОТОРЫЕ ХАТЫ́БЫ НАМЕРЕННО ПРОИЗНОСЯТ СВОИ ПРОПОВЕДИ В РИФМУ И В СТИХОТВОРНОМ СЛОГЕ, ХОТЯ ЗАПРЕТ ЭТОГО ПРИШЁЛ В ДОСТОВЕРНОМ ХАДИСЕ"],["p","<b>См. «ас-Сунан», 75; «аль-Аджуиба ан-нафи′а», стр. 125.</b>"],["sep",""],["p","ГЛАВА № 47 — МНОГИЕ ХАТЫ́БЫ ПОСТОЯННО В ПРОПОВЕДЯХ ПРИВОДЯТ СЛЕДУЮЩИЙ ХАДИС: «ПОИСТИНЕ, В КАЖДУЮ НОЧЬ РАМАДАНА ВСЕМОГУЩИЙ И ВЕЛИКИЙ АЛЛАХ ОСВОБОЖДАЕТ ШЕСТЬСОТ ТЫСЯЧ ЧЕЛОВЕК ОТ ОГНЯ, А В ПОСЛЕДНЮЮ НОЧЬ ОН ОСВОБОЖДАЕТ ОТ ОГНЯ СТОЛЬКО ЖЕ, СКОЛЬКО ОН ОСВОБОДИЛ ВО ВСЕ ПРОШЛЫЕ НОЧИ ВМЕСТЕ ВЗЯТЫЕ». ОНИ ПРИВОДЯТ ЭТОТ ХАДИС В КОНЦЕ ПЯТНИЧНОЙ ПРОПОВЕДИ, ПРОИЗНОСИМОЙ В МЕСЯЦЕ РАМАДАН, ИЛИ В КОНЦЕ ПРАЗДНИЧНОЙ ПРОПОВЕДИ, ХОТЯ ХАДИС ЯВЛЯЕТСЯ ЛОЖНЫМ."],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 125.</b>"],["sep",""],["c","ГЛАВА № 48 — НЕКОТОРЫЕ ЛЮДИ НЕ СОВЕРШАЮТ МОЛИТВУ ПРИВЕТСТВИЯ МЕЧЕТИ, ЕСЛИ ОНИ ВХОДЯТ В МЕЧЕТЬ ТОГДА, КОГДА ХАТЫ́Б УЖЕ ПРОИЗНОСИТ ПРОПОВЕДЬ"],["p","<b>См. «аль-Мухалля», 5/69, Ибн Хазма; а также «аль-Аджуиба ан-нафи′а», стр. 126. </b>"],["sep",""],["p","ГЛАВА № 49 — НЕКОТОРЫЕ ХАТЫ́БЫ ПРЕРЫВАЮТ ПРОПОВЕДЬ, ЕСЛИ ВИДЯТ, ЧТО КТО-ТО ВОШЁЛ В МЕЧЕТЬ И НАЧАЛ СОВЕРШАТЬ МОЛИТВУ ПРИВЕТСТВИЯ МЕЧЕТИ, И ВЕЛЯТ ЕМУ ПРЕКРАТИТЬ ЭТУ МОЛИТВУ, ХОТЯ ДАННОЕ ДЕЙСТВИЕ ПРОТИВОРЕЧИТ ДОСТОВЕРНОМУ ХАДИСУ ОТ ПОСЛАННИКА АЛЛАХА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) И ТОМУ, ЧТО ОН, НАОБОРОТ, ВЕЛЕЛ СОВЕРШАТЬ ЭТУ МОЛИТВУ"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 126.</b>"],["sep",""],["p","ГЛАВА № 50 — НЕКОТОРЫЕ ХАТЫ́БЫ ВО ВРЕМЯ ВТОРОЙ ПРОПОВЕДИ НЕ УВЕЩЕВАЮТ ЛЮДЕЙ, НЕ НАСТАВЛЯЮТ ИХ, НЕ НАПОМИНАЮТ И НЕ ПОБУЖДАЮТ К БЛАГОМУ, А ЦЕЛИКОМ ПОСВЯЩАЮТ ЭТУ ПРОПОВЕДЬ МОЛЬБАМ И ПРИЗЫВУ БЛАГОСЛОВЕНИЯ НА ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)"],["p","<b>См. «ас-Сунан», 56; «Нур уль-баян филь кашф ′ан бида′ ахири ззаман», 445; «аль-Аджуиба ан-нафи′а», стр. 126.</b>"],["sep",""],["c","ГЛАВА № 51 — НЕКОТОРЫЕ ХАТЫ́БЫ ОСОБЕННО СИЛЬНО ПОДНИМАЮТ ГОЛОС ИМЕННО В ТОТ МОМЕНТ, КОГДА ПРОСЯТ БЛАГОСЛОВЕНИЯ ДЛЯ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)"],["p","<b>См. «аль-Ба′ис», 65; «аль-Аджуиба ан-нафи′а», стр. 126.</b>"],["sep",""],["c","ГЛАВА № 52 — НЕКОТОРЫЕ ХАТЫ́БЫ ОСОБЕННО СИЛЬНО ПОДНИМАЮТ ГОЛОС ИМЕННО В ТОТ МОМЕНТ, КОГДА ЧИТАЮТ АЯТ: «ВОИСТИНУ, АЛЛАХ И ЕГО АНГЕЛЫ БЛАГОСЛОВЛЯЮТ ПРОРОКА»."],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 127.</b>"],["sep",""],["h2","ГЛАВА № 53 — НЕКОТОРЫЕ ХАТЫ́БЫ, КОГДА ПРОИЗНОСЯТ ИМЯ АЛЛАХА ИЛИ ИМЕНА КАКИХ-ЛИБО ПРАВЕДНИКОВ, ПРОИЗНОСЯТ ИХ КРИКОМ"],["p","<b>См. «аль-Манар», 18/559; «аль-Аджуиба ан-нафи′а», стр. 127.</b>"],["sep",""],["c","ГЛАВА № 54 — ЕСЛИ КАКОЙ-ЛИБО ИНОВЕРЕЦ ПРИНЯЛ ИСЛАМ В ТЕЧЕНИЕ НЕДЕЛИ, В ПЯТНИЦУ ЕГО ПРИВОДЯТ К ХАТЫ́БУ, КОТОРЫЙ СТОИТ НА МИНБАРЕ, ЧТОБЫ ОН ЗАЯВИЛ О СВОЁМ ИСЛАМЕ ПЕРЕД ЛЮДЬМИ, А ХАТЫ́Б РАДИ ЭТОГО ДАЖЕ ПРЕРЫВАЕТ ПРОПОВЕДЬ"],["p","<b>См. «аль-Мадхаль», 2/171; «аль-Аджуиба ан-нафи′а», стр. 127.</b>"],["sep",""],["c","ГЛАВА № 55 — НЕКОТОРЫЕ ХАТЫ́БЫ ВО ВРЕМЯ ВТОРОЙ ПРОПОВЕДИ МЕЛОДИЧНЫМ ГОЛОСОМ УПОМИНАЮТ ИМЕНА ХАЛИФОВ, ВЛАСТИТЕЛЕЙ ИЛИ СУЛТАНОВ<sup class=\"fn\">483</sup>"],["n",[[483,"Здесь в сносках шейх аль-Альбани добавил: «Мы не знаем, чтобы кто-либо из предшественников, например, из числа сподвижников, табиинов или их последователей, поступал таким образом»."]]]],[["p","<b>См. «аль-И′тисам», 1/17-18, 2/177; «аль-Манар», 6/139, 18/305, 558, 31/55; «аль-Аджуиба ан-нафи′а», стр. 127.</b>"],["sep",""],["h2","ГЛАВА № 56 — ХАТЫ́Б ОБРАЩАЕТСЯ С МОЛЬБАМИ ЗА ВОИНОВ И ТЕХ, КТО СТЕРЕЖЁТ ГРАНИЦЫ"],["p","<b>См. «аль-И′тисам», 1/18; «аль-Аджуиба ан-нафи′а», стр. 128.</b>"],["sep",""],["h2","ГЛАВА № 57 — ХАТЫ́Б ВЕДЁТ ПРОПОВЕДЬ, А В ЭТО ВРЕМЯ МУАЗЗИНЫ ГРОМКИМ ГОЛОСОМ ОБРАЩАЮТСЯ С МОЛЬБАМИ ЗА СУЛТАНОВ"],["p","<b>См. «аль-Манар», 18/558; «ас-Сунан», 25; «аль-Аджуиба ан-нафи′а», стр. 128.</b>"],["sep",""],["h2","ГЛАВА № 58 — ХАТЫ́Б ВЗЫВАЕТ К АЛЛАХУ, ДЕЛАЯ ПАУЗЫ МЕЖДУ ПРЕДЛОЖЕНИЯМИ, ЧТОБЫ МУАЗЗИНЫ МОГЛИ ГОВОРИТЬ: «АМИН»"],["p","<b>См. «Шарх ат-тарика аль-Мухаммадия», 3/323; «аль-Аджуиба ан-нафи′а», стр. 128.</b>"],["sep",""],["c","ГЛАВА № 59 — КОГДА ХАТЫ́Б ПРОСИТ ДЛЯ СПОДВИЖНИКОВ ДОВОЛЬСТВА АЛЛАХА, А ДЛЯ ПРАВИТЕЛЕЙ — ПОМОЩИ, МУАЗЗИНЫ ГРОМКО ГОВОРЯТ: «АМИН»"],["p","<b>См. «Шарх ат-тарика аль-Мухаммадия», 3/323; «аль-Аджуиба ан-нафи′а», стр. 128.</b>"],["sep",""],["h2","ГЛАВА № 60 — ПРОИЗНЕСЕНИЕ ПРОПОВЕДИ НАРАСПЕВ"],["p","<b>См. «аль-Ибда′», 27; «аль-Аджуиба ан-нафи′а», стр. 128.</b>"],["sep",""],["h2","ГЛАВА № 61 — КОГДА ХАТЫ́Б ПРОИЗНОСИТ КАКУЮ-ЛИБО МОЛЬБУ, ОН ПОДНИМАЕТ РУКИ<sup class=\"fn\">484</sup>"],["n",[[484,"Сказал шейх ислама Ибн Теймия в «аль-Ихтиярат аль-′ильмия», 48: <i>«Если имам произносит проповедь, ему нежелательно поднимать руки во время мольбы, ведь пророк (да благословит его Аллах и приветствует), когда взывал к Аллаху, только указывал своим пальцем». </i>"]]],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 128.</b>"],["sep",""],["h2","ГЛАВА № 62 — КОГДА ХАТЫ́Б ПРОИЗНОСИТ КАКУЮ-ЛИБО МОЛЬБУ, ПРИСУТСТВУЮЩИЕ В МЕЧЕТИ ПОДНИМАЮТ РУКИ И ГОВОРЯТ: «АМИН»<sup class=\"fn\">485</sup>"],["n",[[485,"Здесь в сносках шейх аль-Альбани добавил: «Упомянул Ибн ′Абидин в «Хашие», 1/768, что, согласно более верному мнению, те, кто поступают так, впадают в грех»."]]],["p","<b>См. «аль-Ба′ис», 64, 65; «аль-Аджуиба ан-нафи′а», стр. 129.</b>"],["sep",""],["c","ГЛАВА № 63 — ВО ВРЕМЯ ВТОРОЙ ПЯТНИЧНОЙ ПРОПОВЕДЬ ХАТЫ́Б МОНОТОННО ПРОИЗНОСИТ МОЛЬБУ И ПОДНИМАЕТ РУКИ К НЕБУ. МЫ НЕ ЗНАЕМ ЭТОМУ ОСНОВЫ В СУННЕ"],["p","<b>См. «Мухтасар Сахих аль-Бухари», 1/282. </b>"],["sep",""],["c","ГЛАВА № 64 — ХАТЫ́Б ПОСТОЯННО ЗАКАНЧИВАЕТ СВОЮ ПРОПОВЕДЬ ЧТЕНИЕМ СЛОВ АЛЛАХА: «ВОИСТИНУ, АЛЛАХ ПОВЕЛЕВАЕТ БЛЮСТИ СПРАВЕДЛИВОСТЬ, ДЕЛАТЬ ДОБРО…»<sup class=\"fn\">486</sup> ИЛИ ЖЕ СЛОВАМИ: «ПОМНИТЕ ОБ АЛЛАХЕ, И ОН БУДЕТ ПОМНИТЬ О ВАС»."],["n",[[486,"Сура «ан-Нахль», аят 90."]]],["p","<b>См. «аль-Мадхаль», 2/271; «ас-Сунан», 57; «аль-Аджуиба ан-нафи′а», стр. 129.</b>"],["sep",""],["h2","ГЛАВА № 65 — ЧРЕЗМЕРНОЕ ЗАТЯГИВАНИЕ ПРОПОВЕДИ И УКОРАЧИВАНИЕ МОЛИТВЫ<sup class=\"fn\">487</sup>"],["n",[[487,"Здесь в сносках шейх аль-Альбани добавил: «Потому что, согласно Сунне, нужно удлинять молитву и укорачивать проповедь. Если же кто-то поступает наоборот (это стало обычаем большинства хатыбов сегодня), то нет сомнений в том, что это является новшеством»."]]],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 129.</b>"],["sep",""],["h2","ГЛАВА № 66 — НЕКОТОРЫЕ ЛЮДИ ОБТИРАЮТСЯ РУКАМИ О СПИНУ ХАТЫ́БА, КОГДА ОН СПУСКАЕТСЯ С МИНБАРА"]],[["p","<b>См. «аль-Ибда′», 79; «Ислях аль-масаджид», 78; «ас-Сунан», 54; «Нур уль-баян», 44; «аль-Аджуиба ан-нафи′а», стр. 130.</b>"],["sep",""],["c","ГЛАВА № 67 — НЕКОТОРЫЕ ЛЮДИ СЧИТАЮТ КОЛИЧЕСТВО СОБРАВШИХСЯ В НЕКОТОРЫХ МАЛЕНЬКИХ МЕЧЕТЯХ В ПЯТНИЦУ, ЧТОБЫ ПОСМОТРЕТЬ, ДОСТИГЛО ЛИ ИХ КОЛИЧЕСТВО СОРОКА ЧЕЛОВЕК"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 130.</b>"],["sep",""],["h2","ГЛАВА № 68 — ПРОВЕДЕНИЕ ПЯТНИЧНЫХ МОЛИТВ В МАЛЕНЬКИХ МЕЧЕТЯХ<sup class=\"fn\">488</sup>"],["n",[[488,"Речь идёт о том, что люди должны собираться на пятничную молитву в стольких мечетях, сколько вмещают их всех. Если они все помещаются в одной главной мечети города, то пятничная молитва должна проводиться только в ней. Если же, например, они вмещаются целиком в пяти мечетях, то нельзя проводить молитву в шести, семи, восьми и т. д. А Аллах знает лучше!"]]],["p","<b>См. «Ислях аль-масаджид», 63; «аль-Аджуиба ан-нафи′а», стр. 130.</b>"],["sep",""],["h2","ГЛАВА № 69 — ИМАМ НАЧИНАЕТ МОЛИТВУ ДО ТОГО, КАК МОЛЯЩИЕСЯ ВЫРОВНЯЛИ РЯДЫ"],["p","<b>См. «Ислях аль-масаджид», 99-100; «аль-Аджуиба ан-нафи′а», стр. 131.</b>"],["sep",""],["h2","ГЛАВА № 70 — ЛЮДИ ЦЕЛУЮТ РУКУ ПОСЛЕ МОЛИТВЫ"],["p","<b>См. «Ислях аль-масаджид», 99; «аль-Аджуиба ан-нафи′а», стр. 131.</b>"],["sep",""],["h2","ГЛАВА № 71 — НЕКОТОРЫЕ ЛЮДИ ПОСЛЕ ЗАВЕРШЕНИЯ ПЯТНИЧНОЙ МОЛИТВЫ ГОВОРЯТ: «ПУСТЬ АЛЛАХ ПРИМЕТ ОТ НАС И ОТ ВАС!»"],["p","<b>См. «ас-Сунан», 54; «аль-Аджуиба ан-нафи′а», стр. 131.</b>"],["sep",""],["h2","ГЛАВА № 72 — СОВЕРШЕНИЕ ОБЕДЕННОЙ МОЛИТВЫ (ЗУХР) ПОСЛЕ ПЯТНИЧНОЙ"],["p","<b>См. «ас-Сунан», 10, 123; «Ислях аль-масаджид», 51-53; «аль-Манар», 23/259, 497, 34/120; «аль-Аджуиба ан-нафи′а», стр. 132.</b>"],["sep",""],["p","ГЛАВА № 73 — НЕКОТОРЫЕ ЖЕНЩИНЫ В ПЯТНИЦУ ВСТАЮТ У ДВЕРЕЙ МЕЧЕТИ С РЕБЕНКОМ, КОТОРЫЙ ЕЩЕ НЕ УМЕЕТ ХОДИТЬ. ОНИ ПОДВЯЗЫВАЮТ БОЛЬШИЕ ПАЛЬЦЫ ЕГО НОГ С ПОМОЩЬЮ НИТИ, А ЗАТЕМ ПРОСЯТ ПЕРВОГО ЧЕЛОВЕКА, ВЫХОДЯЩЕГО С МЕЧЕТИ РАЗВЯЗАТЬ ЭТУ НИТЬ. ОНИ СЧИТАЮТ, ЧТО ЧЕРЕЗ ДВЕ НЕДЕЛИ ПОСЛЕ ЭТОГО ОБРЯДА РЕБЕНОК ОБЯЗАТЕЛЬНО НАУЧИТЬСЯ ХОДИТЬ"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 132.</b>"],["sep",""],["p","ГЛАВА № 74 — НЕКОТОРЫЕ ЛЮДИ ВСТАЮТ ВОЗЛЕ ДВЕРЕЙ МЕЧЕТИ СО СТАКАНОМ ВОДЫ, ЧТОБЫ КАЖДЫЙ ВЫХОДЯЩИЙ ИЗ МЕЧЕТИ СЛЕГКА ПОПЛЕВАЛ В НЕГО, И ОНИ ДУМАЮТ, ЧТО ИЗ-ЗА ЭТОГО ВОДА ОБРЕТЕТ БЛАГОДАТЬ (БАРАКУ) И ПОСПОСОБСТВУЕТ ИЗЛЕЧЕНИЮ ОТ БОЛЕЗНЕЙ"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 133.</b>"],["sep",""],["c","ГЛАВА № 75 — В ОДНОЙ ИСЛАМСКОЙ СТРАНЕ СОТНИ МЕЧЕТЕЙ ЛИШАЮТ ПРОИЗНЕСЕНИЯ АЗАНА, ТРАНСЛИРУЯ ОДИН АЗАН НА ВСЕ МЕЧЕТИ. ЭТО НАРУШАЕТ ТО, В ЧЁМ БЫЛИ ЕДИНОГЛАСНЫ ВСЕ ИСЛАМСКИЕ ЗЕМЛИ И В ПРОШЛЫЕ ВРЕМЕНИ, И СЕЙЧАС"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 133.</b>"],["sep",""],["h2","ГЛАВА № 76 — В НЕКОТОРЫХ ИСЛАМСКИХ СТРАНАХ МУАЗЗИНЫ НЕ ПРОИЗНОСЯТ АЗАН, НО В МЕЧЕТИ ВКЛЮЧАЮТ ЗАПИСАННЫЙ НА КАССЕТУ АЗАН"],["p","<b>См. «аль-Аджуиба ан-нафи′а», стр. 133.</b>"],["sep",""],["h2","ГЛАВА № 77 — ПЕРВЫЙ АЗАН В ПЯТНИЦУ ЯВЛЯЕТСЯ НОВШЕСТВОМ"],["h3","<b>Сказал шейх аль-Альбани, да помилует его Всевышний Аллах, в «аль-Аджуиба ан-нафи′а», стр. 21-22:</b>"]],[["p","«Передал аль-Куртуби в своём «Тафсире», 18/100, что аль-Мауарди сказал: <i>«Что касается первого азана, то он является новшеством. ′Усман велел произносить его, когда Медина расширилась, и в ней стало много людей, чтобы люди смогли успеть на проповедь». </i>"],["p","И если дело обстоит так, то сегодня в азане ′Усмана нет пользы, и это запрещено. Особенно в этой ситуации, когда речь идёт о добавлении к Сунне посланника Аллаха (да благословит его Аллах и приветствует) без какой-либо уважительной причины. И, вероятно, именно поэтому ′Али ибн Аби Талиб (да будет доволен им Аллах) в Куфе остановился на Сунне и не действовал согласно тому, что добавил ′Усман, как это передал аль-Куртуби."],["p","Сказал Ибн ′Умар (да будет доволен Аллах им и его отцом): <i>«Когда пророк (да благословит его Аллах и приветствует) поднимался на минбар, Биляль произносил азан, а когда пророк (да благословит его Аллах и приветствует) заканчивал проповедь, Биляль произносил икаму на молитву. Первый же азан является новшеством». </i>Передал Абу Тахир в «аль-Фауаид»."],["p","Мы считаем, что следует ограничиться тем азаном, который был во времена пророка (да благословит его Аллах и приветствует), и что этот азан должен произноситься тогда, когда имам появляется в мечети и поднимается на минбар, ибо сейчас нет причины, которая делала бы разрешенной азан ′Усмана. Необходимо следовать за Сунной пророка (да благословит его Аллах и приветствует)»."],["h2","РАЗДЕЛ ПЯТНАДЦАТЫЙ — НОВШЕСТВА, СВЯЗАННЫЕ С ПОХОРОНАМИ"],["h2","ГЛАВА № 1 — НОВШЕСТВА, СОВЕРШАЕМЫЕ ДО СМЕРТИ ЧЕЛОВЕКА"],["p","ВОПРОС № 1: НЕКОТОРЫЕ ЛЮДИ ДУМАЮТ, ЧТО ШАЙТАНЫ ПРИХОДЯТ К УМИРАЮЩЕМУ В ОБЛИКЕ ЕГО РОДИТЕЛЕЙ В ОДЕЖДАХ ИУДЕЕВ ИЛИ ХРИСТИАН, ЧТОБЫ ПРЕДЛОЖИТЬ ЕМУ ПРИНЯТЬ ИНУЮ РЕЛИГИЮ И ТЕМ САМЫМ ВВЕСТИ ЕГО В ЗАБЛУЖДЕНИЕ"],["p","Ибн Хаджар аль-Хейтами в «аль-Фатауа аль-хадисия» передал, что ас-Суюты сказал: <i>«Это не пришло (в религиозных текстах)»</i><sup class=\"fn\">489</sup>."],["n",[[489,"Это суеверие распространил среди людей аль-Газали. Он привёл его в книге «Кашф ′улюм аль-ахира». Сказал Ибн Хаджар в «Фатх уль-Бари», 11/434: <i>«Он (аль-Газали) в этой книге приводит много хадисов, у которых нет никакой основы, посему не следует обольщаться этими хадисами». </i>"]]],["p","<b>Шейх упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 307; «Тальхис аль-Джанаиз», стр. 96. </b>"],["sep",""],["h2","ВОПРОС № 2: НЕКОТОРЫЕ ЛЮДИ КЛАДУТ КОРАН ВОЗЛЕ ГОЛОВЫ УМИРАЮЩЕГО"],["p","<b>Шейх упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 307; «Тальхис аль-Джанаиз», стр. 96. </b>"],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ ПЕРЕД СМЕРТЬЮ НАПОМИНАЮТ ЧЕЛОВЕКУ О НЕОБХОДИМОСТИ ПРИЗНАТЬ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) И ИМАМОВ ИЗ ЧИСЛА ЧЛЕНОВ ЕГО СЕМЬИ<sup class=\"fn\">490</sup>"],["n",[[490,"Подобное упоминается в книгах шиитов и рафидитов."]]]],[["p","<b>Шейх упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 307; «Тальхис аль-Джанаиз», стр. 96. </b>"],["sep",""],["h2","ВОПРОС № 4: ЧТЕНИЕ СУРЫ «ЙА СИН» ВОЗЛЕ УМИРАЮЩЕГО"],["p","<b>Шейх упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 20, 307; «Тальхис аль-Джанаиз», стр. 11, 96. </b>"],["p","<b>Также наш шейх, да помилует его Всевышний Аллах, в «Ахкам аль-джанаиз», стр. 243, передал слова шейха ислама Ибн Теймии, да помилует его Всевышний Аллах. Тот сказал в книге «аль-Ихтиярат аль-′ильмия», стр. 53:</b>"],["p","«Чтение Корана умершему уже после смерти — это новшество, и это в отличие от чтения Корана умирающему. Желательно читать умирающему суру \"Йа Син\"»."],["h3","<b>Шейх аль-Альбани сказал, комментируя эти слова: </b>"],["p","«Хадис о чтении суры «Йа Син» является слабым, а желательность — это религиозное постановление. Желательность не может быть установлена через слабый хадис. Это известно из слов самого Ибн Теймии в некоторых его трудах»<sup class=\"fn\">491</sup>."],["n",[[491,"Ученые, которые считали это желательным, говорили о том, что в данной суре упоминаются единобожие, Судный День, благая весть о Рае для того, кто умер, исповедуя единобожие, и по этой причине, если умирающий слушает эту суру, он испытывает облегчение и радость. А Аллах знает лучше! Сказал шейх Ибн ′Усеймин, да помилует его Аллах: <i>«Чтение суры «Йа Син» возле умирающего является желательным действием по мнению многих ученых, ибо пророк, да благословит его Аллах и приветствует, сказал: </i><b><i>«Читайте суру \"Йа Син\" вашим умирающим». </i></b><i>Однако относительно этого хадиса есть критика со стороны ученых. Некоторые ученые назвали его слабым. Что касается тех ученых, которые посчитали его достоверным, то у них чтение этой суры умирающему является желательным. А у тех ученых, которые посчитали хадис слабым, чтение этой суры не является желательным. А Аллах знает лучше!». </i>См. «Фатауа Ибн ′Усеймин», 17/72. Речь идёт о чтении Корана именно умирающему. Что же касается чтения Корана тому, кто уже умер, то это, без сомнения, является новшеством. Но у тех, кто читает Коран умирающим перед смертью, есть большие ученые, за которыми они последовали (в частности, шейх ислама Ибн Теймия и многие из числа современников), поэтому если кто-то будет практиковать данное действие, не следует враждовать с ним и называть его сторонником новшеств. А Аллах знает лучше!"]]],["sep",""],["h2","ВОПРОС № 5: ОБРАЩЕНИЕ УМИРАЮЩЕГО В СТОРОНУ КААБЫ"],["p","Подобное порицал Са′ид ибн уль-Мусеййяб, как это пришло в «аль-Мухалля», 5/174. Также это порицал Малик, как это пришло в «аль-Мадхаль», 3/229-230. А хадис на эту тему не является достоверным."],["p","<b>Шейх аль-Альбани упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 20, 307; «Тальхис аль-Джанаиз», стр. 11, 96.</b>"],["sep",""],["h2","ГЛАВА № 2 — НОВШЕСТВА, СОВЕРШАЕМЫЕ ПОСЛЕ СМЕРТИ ЧЕЛОВЕКА"]],[["p","ВОПРОС № 1: ШИИТЫ ГОВОРЯТ: «ЧЕЛОВЕЧЕСКОЕ ТЕЛО СТАНОВИТСЯ НЕЧИСТЫМ (НАДЖАС) ПОСЛЕ СМЕРТИ, ЗА ИСКЛЮЧЕНИЕМ \"МА′СУМОВ\"<sup class=\"fn\">492</sup> И МУЧЕНИКОВ, А ТАКЖЕ ТОГО, КОГО ОБЯЗАТЕЛЬНО БЫЛО УБИТЬ, НО ОН СОВЕРШИЛ ПОЛНОЕ ОМОВЕНИЕ (ГУСЛЬ) ПЕРЕД КАЗНЬЮ, А ЗАТЕМ ЕГО УБИЛИ ПО ЭТОЙ ПРИЧИНЕ»<sup class=\"fn\">493</sup>."],["n",[[492,"Слово «ма′сум» означает «защищенный от грехов и любых ошибок». Так шииты называют своих имамов."],[493,"На самом же деле, человеческое тело не становится нечистым после смерти. Это касается как верующих, так и неверующих. Аллах сказал: <b>«Мы почтили сынов Адама». </b>(Сура «аль-Исра», аят 70). Этого мнения придерживались маликиты, шафииты и ханбалиты. А Аллах знает лучше!"]]],["p","<b>Шейх аль-Альбани упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 308; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["p","ВОПРОС № 2: НЕКОТОРЫЕ ЛЮДИ ТРЕБУЮТ, ЧТОБЫ ЖЕНЩИНЫ, У КОТОРЫХ МЕНСТРУАЦИИ И ПОСЛЕРОДОВЫЕ КРОВОТЕЧЕНИЯ, А ТАКЖЕ ЛЮДИ, КОТОРЫЕ ПРЕБЫВАЮТ В ПОЛОВОМ ОСКВЕРНЕНИИ, НЕ ВХОДИЛИ К ПОКОЙНОМУ"],["p","<b>Шейх аль-Альбани упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 308; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ СЧИТАЮТ, ЧТО ТОТ, КТО ПРИСУТСТВОВАЛ ПРИ СМЕРТИ ЧЕЛОВЕКА, ДОЛЖЕН ОСТАВИТЬ ВСЕ ДЕЛА И РАБОТУ НА СЕМЬ ДНЕЙ"],["p","<b>Шейх аль-Альбани упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 308; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 4: НЕКОТОРЫЕ ЛЮДИ ДУМАЮТ, ЧТО ДУХ ПОКОЙНОГО ЛЕТАЕТ ВОКРУГ ТОГО МЕСТА, ГДЕ ОН СКОНЧАЛСЯ"],["p","<b>Шейх аль-Альбани упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 308; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 5: НЕКОТОРЫЕ ЛЮДИ В ПЕРВУЮ НОЧЬ С МОМЕНТА СМЕРТИ ЧЕЛОВЕКА ОСТАВЛЯЮТ ВОЗЛЕ ЕГО ТЕЛА ГОРЯЩУЮ СВЕЧУ ДО САМОГО УТРА"],["p","<b>Шейх аль-Альбани упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 308; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 6: НЕКОТОРЫЕ ЛЮДИ КЛАДУТ ЗЕЛЕНУЮ ВЕТОЧКУ В КОМНАТЕ, ГДЕ СКОНЧАЛСЯ ПОКОЙНЫЙ"],["p","<b>Шейх аль-Альбани упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 308; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 7: ЧТЕНИЕ КОРАНА ВОЗЛЕ ПОКОЙНИКА ДО ТЕХ ПОР, ПОКА ЕГО ТЕЛО НЕ ОМОЮТ"],["p","<b>Шейх аль-Альбани упомянул этот вопрос в «Ахкам аль-джанаиз», стр. 308; «Тальхис аль-Джанаиз», стр. 97.</b>"],["h3","<b>Также сказал наш шейх в «Ахкам аль-джанаиз», стр. 243:</b>"],["p","«Сказал шейх ислама (Ибн Теймия) в «аль-Ихтиярат аль-′ильмия», стр. 53: <i>\"Чтение Корана умершему уже после смерти — это новшество\"</i>»."],["sep",""],["h2","ВОПРОС № 8: СТРИЖКА НОГТЕЙ УМЕРШЕГО И БРИТЬЁ ЕГО ЛОБКА"],["p","<b>См. «аль-Мудаввана», 1/180, Малик; «Мадхаль», 3/240; «Ахкам аль-джанаиз», стр. 308; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 9: НЕКОТОРЫЕ ЛЮДИ ЗАСОВЫВАЮТ КУСОК ХЛОПКОВОЙ ТКАНИ В ЗАДНИЙ ПРОХОД УМЕРШЕГО, ЕГО ГОРЛО И НОС<sup class=\"fn\">494</sup>"],["n",[[494,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Это разрешено только в исключительных ситуациях, например, если больной чем-то болел, и есть опасность, что из него может что-то вытечь, что испачкает или осквернит его саван». </i>"]]]],[["p","<b>См. «аль-Мудаввана», 1/180, Малик; «аль-Мадхаль», 3/240; «Ахкам аль-джанаиз», стр. 309; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 10: НЕКОТОРЫЕ ЛЮДИ СЫПЯТ ПЕСОК НА ГЛАЗА УМЕРШЕГО, ГОВОРЯ: «НЕ ЗАПОЛНИТ ГЛАЗА ПОТОМКА АДАМА НИЧЕГО, КРОМЕ ЗЕМЛИ»"],["p","<b>См. «аль-Мадхаль», 3/261; «Ахкам аль-джанаиз», стр. 309; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 11: ЧЛЕНЫ СЕМЬИ УМЕРШЕГО ОТКАЗЫВАЮТСЯ ОТ ЕДЫ, ПОКА ЕГО НЕ ЗАХОРОНЯТ"],["p","<b>См. «аль-Мадхаль», 3/276; «Ахкам аль-джанаиз», стр. 309; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 12: ПЛАЧ ПО УМЕРШЕМУ ПО УТРАМ И ВЕЧЕРАМ"],["p","<b>См. «аль-Мадхаль», 3/276; «Ахкам аль-джанаиз», стр. 309; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 13: ЧЕЛОВЕК РВЁТ НА СЕБЕ ОДЕЖДУ, ЕСЛИ У НЕГО СКОНЧАЛСЯ ОТЕЦ ИЛИ БРАТ<sup class=\"fn\">495</sup>"],["n",[[495,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Так поступают (шииты) имамиты, как это пришло в книге «Мифтах аль-карама», 1/509». </i>"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 309; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["h2","ВОПРОС № 14: НЕКОТОРЫЕ ЛЮДИ ОСТАВЛЯЮТ БОРОДУ, ПОКАЗЫВАЯ СВОЮ ПЕЧАЛЬ ПО ПОКОЙНОМУ"],["h3","<b>Сказал шейх, да помилует его Всевышний Аллах, в «Ахкам аль-джанаиз», стр. 43:</b>"],["p","«Некоторые мужчины оставляют бороду на малое количество дней, показывая свою печаль по покойному, после чего они вновь начинают сбривать её. Это оставление бороды относится к «распусканию волос», как это очевидно<sup class=\"fn\">496</sup>. К тому же это является новшеством»<sup class=\"fn\">497</sup>."],["n",[[496,"Шейх имеет в виду то, что пришло в хадисе. Асид ибн Аби Асид передаёт от одной женщины из числа тех, кто присягал посланнику Аллаха (да благословит его Аллах и приветствует): <i>«Среди того одобряемого, в чём мы поклялись не ослушиваться его, были следующие действия: мы не должны были царапать лицо, громко причитать, рвать на себе одежду и распускать волосы».</i> Абу Дауд, 3131; ат-Табарани, 25/184; аль-Бейхакы, 7372. Речь идёт о выражении скорби таким образом. Подобные действия противоречат терпению и смирению и указывают на недовольство предопределением Всевышнего."],[497,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Само по себе опускание бороды из-за следования пророку (да благословит его Аллах и приветствует) является обязательным действием, как это очевидно». </i>"]]],["h3","<b>Также шейх, да помилует его Всевышний Аллах, сказал в «Адаб аз-зифаф», стр. 207-208:</b>"],["p","«Некоторые из них впали в ещё большее заблуждение. Они считают благим делом оставление бороды по причине смерти своего близкого родственника. <b>«Воистину, слепнут не глаза, а слепнут сердца, находящиеся в груди»</b><sup class=\"fn\">498</sup>."],["n",[[498,"Сура «аль-Хаджж», аят 46."]]],["sep",""],["h2","ВОПРОС № 15: НЕКОТОРЫЕ ЛЮДИ ПОСЛЕ СМЕРТИ ЧЕЛОВЕКА ПЕРЕВОРАЧИВАЮТ КОВРЫ И НАКРЫВАЮТ ТКАНЬЮ ЗЕРКАЛА И ЛЮСТРЫ"]],[["p","<b>См. «Ахкам аль-джанаиз», стр. 309; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["p","ВОПРОС № 16: НЕКОТОРЫЕ ЛЮДИ ПОСЛЕ СМЕРТИ ЧЕЛОВЕКА ВЫЛИВАЮТ ВСЮ ВОДУ, КОТОРАЯ ХРАНИЛАСЬ ДОМА. ОНИ СЧИТАЮТ, ЧТО ОНА СТАНОВИТСЯ НЕЧИСТОЙ (НАДЖАС), ГОВОРЯ: «ПОКИДАЯ ТЕЛО, ДУША ПОКОЙНОГО НЫРЯЕТ В ЭТУ ВОДУ»"],["p","<b>См. «аль-Мадхаль»; «Ахкам аль-джанаиз», стр. 309; «Тальхис аль-Джанаиз», стр. 97.</b>"],["sep",""],["p","ВОПРОС № 17: ЕСЛИ КТО-ЛИБО ЧИХНУЛ НА ЕДУ, ЛЮДИ ГОВОРЯТ ЕМУ: «ПОГОВОРИ С ТАКИМ-ТО (ИЛИ С ТАКОЙ-ТО)», НАЗЫВАЯ КОГО-ТО ИЗ СВОИХ ЛЮБИМЫХ, КОТОРЫЕ ЕЩЕ ЖИВЫ, И ГОВОРЯ: «А ИНАЧЕ ОН УМРЁТ»"],["p","<b>См. «аль-Мадхаль»; «Ахкам аль-джанаиз», стр. 309; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 18: НЕКОТОРЫЕ ЛЮДИ ОТКАЗЫВАЮТСЯ ОТ ПРИНЯТИЯ В ПИЩУ МУЛЮХИЙИ<sup class=\"fn\">499</sup> И РЫБЫ В ПЕРИОД ТРАУРА ПО ПОКОЙНОМУ"],["n",[[499,"Название блюда — густого супа из зелени, риса и баранины."]]],["p","<b>См. «аль-Мадхаль», 3/281; «Ахкам аль-джанаиз», стр. 310; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 19: НЕКОТОРЫЕ ЛЮДИ ОТКАЗЫВАЮТСЯ ОТ ПРИНЯТИЯ В ПИЩУ МЯСА, ЖАРЕНЫХ ПОТРОХОВ И КУББЫ<sup class=\"fn\">500</sup> В ПЕРИОД ТРАУРА ПО ПОКОЙНОМУ"],["n",[[500,"Название блюда — жаренные шарики из мяса, дроблёной пшеницы или дроблёного риса, муки, приправ."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 310; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 20: СУФИИ ГОВОРЯТ: «КТО ОПЛАКИВАЕТ ПОКОЙНОГО, ТОТ ПОКИНУЛ ПУТЬ ПОЗНАВШИХ АЛЛАХА»"],["p","<b>См. «Тальбис Иблис», стр. 340-342, Ибн уль-Джаузи; «Ахкам аль-джанаиз», стр. 310; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 21: НЕКОТОРЫЕ ЛЮДИ ТРИ ДНЯ НЕ СТИРАЮТ ОДЕЖДУ ПОКОЙНОГО, ДУМАЯ, ЧТО ЭТО ЗАЩИЩАЕТ ЕГО ОТ МОГИЛЬНЫХ МУК"],["p","<b>См. «аль-Мадхаль», 3/276; «Ахкам аль-джанаиз», стр. 310; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["p","ВОПРОС № 22: НЕКОТОРЫЕ ЛЮДИ ГОВОРЯТ: «ЕСЛИ ЧЕЛОВЕК УМЕР В ПЯТНИЦУ ИЛИ В НОЧЬ НА ПЯТНИЦУ, ТО ОН БУДЕТ ПОДВЕРГНУТ МОГИЛЬНЫМ МУКАМ НА ОДИН ЧАС, А ЗАТЕМ ЕГО НАКАЗАНИЕ ПРЕКРАТИТСЯ И НЕ ВЕРНЕТСЯ ДО САМОГО СУДНОГО ДНЯ»"],["p","<b>Это мнение упомянул шейх ′Али аль-Кари в «Шарх аль-Фикх аль-акбар», стр. 96, и отверг его. См. также «Ахкам аль-джанаиз», стр. 310; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["p","ВОПРОС № 23: НЕКОТОРЫЕ ЛЮДИ ГОВОРЯТ: «ВЕРУЮЩИЙ, КОТОРЫЙ СОВЕРШАЛ ГРЕХИ, ПЕРЕСТАЁТ ПОЛУЧАТЬ НАКАЗАНИЕ В МОГИЛЕ В ПЯТНИЦУ ИЛИ В НОЧЬ НА ПЯТНИЦУ, ПОСЛЕ ЧЕГО НАКАЗАНИЕ НЕ ВОЗВРАЩАЕТСЯ К НЕМУ ДО САМОГО СУДНОГО ДНЯ»<sup class=\"fn\">501</sup>"],["n",[[501,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Это мнение упомянул шейх ′Али аль-Кари в «Шарх аль-Фикх аль-акбар», стр. 91, и отверг его, назвав ложным. А еще более ложными являются слова тех, кто говорит, что неверующих перестают наказывать в могиле по пятницам и в месяц рамадан по причине святости пророка (да благословит его Аллах и приветствует). Шейх (аль-Кари) также передал это мнение и отверг». </i>"]]]],[["p","<b>См. «Ахкам аль-джанаиз», стр. 310; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 24: ОБЪЯВЛЕНИЕ О СМЕРТИ ЧЕЛОВЕКА С МИНАРЕТОВ"],["p","<b>См. «аль-Мадхаль», 3/245-246; «Ахкам аль-джанаиз», стр. 310; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 25: КОГДА КТО-ТО УМИРАЕТ, НЕКОТОРЫЕ ЛЮДИ ГОВОРЯТ: «ПРОЧТИТЕ \"АЛЬ-ФАТИХУ\" ЗА ДУШУ ТАКОГО-ТО»."],["p","<b>См. «Ахкам аль-джанаиз», стр. 310; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ГЛАВА № 3 — НОВШЕСТВА, СВЯЗАННЫЕ С ОМЫВАНИЕМ ПОКОЙНОГО"],["h2","ВОПРОС № 1: НЕКОТОРЫЕ ЛЮДИ НА ТРИ НОЧИ КЛАДУТ ХЛЕБ И СТАКАН ВОДЫ В ТОМ МЕСТЕ, ГДЕ ОМЫЛИ ПОКОЙНОГО"],["p","<b>См. «аль-Мадхаль», 3/276; «Ахкам аль-джанаиз», стр. 311; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["p","ВОПРОС № 2: НЕКОТОРЫЕ ЛЮДИ НА ТРИ НОЧИ РАЗЖИГАЮТ ЛАМПЫ ИЛИ СВЕТИЛЬНИКИ В ТОМ МЕСТЕ, ГДЕ ОМЫЛИ ПОКОЙНОГО. ЭТИ ЛАМПЫ ГОРЯТ ОТ ЗАКАТА ДО РАССВЕТА. НЕКОТОРЫЕ ОСТАВЛЯЮТ ИХ НА СЕМЬ ДНЕЙ, А НЕКОТОРЫЕ — ЕЩЕ БОЛЬШЕ. ТО ЖЕ САМОЕ ОНИ ДЕЛАЮТ В ТОМ МЕСТЕ, ГДЕ ПОКОЙНЫЙ СКОНЧАЛСЯ"],["p","<b>См. «аль-Мадхаль», 3/276; «Ахкам аль-джанаиз», стр. 311; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ, КОГДА ОМЫВАЮТ ПОКОЙНОГО, ПРОИЗНОСЯТ РАЗНЫЕ ПОМИНАНИЯ (АЗКАРЫ) ПРИ МЫТЬЕ КАЖДОЙ ЧАСТИ ЕГО ТЕЛА"],["p","<b>См. «аль-Мадхаль», 3/329; «Ахкам аль-джанаиз», стр. 311; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 4: НЕКОТОРЫЕ ЛЮДИ ГРОМКО ПОМИНАЮТ АЛЛАХА ВО ВРЕМЯ МЫТЬЯ ПОКОЙНОГО И СОПРОВОЖДЕНИЯ ПОХОРОННОЙ ПРОЦЕССИИ"],["p","<b>См. «Шарх ат-тарика аль-Мухаммадия», 4/22; «Ахкам аль-джанаиз», стр. 311; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 5: НЕКОТОРЫЕ ЖЕНЩИНЫ, ОМЫВАЯ ПОКОЙНУЮ, РАСПУСКАЮТ ЕЙ ВОЛОСЫ И СКЛАДЫВАЮТ ИХ МЕЖ ЕЁ ГРУДЕЙ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 311; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ГЛАВА № 4 — НОВШЕСТВА, СВЯЗАННЫЕ С САВАНОМ И СОПРОВОЖДЕНИЕМ ПОХОРОННОЙ ПРОЦЕССИИ"],["p","ВОПРОС № 1: НЕКОТОРЫЕ ЛЮДИ ПЕРЕВОЗЯТ ПОКОЙНОГО В ДАЛЕКИЕ МЕСТА, ЧТОБЫ ЗАХОРОНИТЬ ЕГО ВОЗЛЕ МОГИЛ ПРАВЕДНЫХ ЛЮДЕЙ (НАПРИМЕР, ЧЛЕНОВ СЕМЬИ ПРОРОКА И Т. П.)"],["p","<b>См. «Ахкам аль-джанаиз», стр. 312; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["p","ВОПРОС № 2: НЕКОТОРЫЕ ЛЮДИ ГОВОРЯТ, ЧТО ПОКОЙНЫЕ В МОГИЛАХ ХВАЛЯТСЯ ДРУГ ПЕРЕД ДРУГОМ КРАСОТОЙ СВОИХ САВАНОВ, И ЕСЛИ КТО-ТО ИЗ ПОКОЙНЫХ ЛЕЖИТ В ДЕШЕВОМ САВАНЕ, ДРУГИЕ СЧИТАЮТ ЭТО ПОЗОРОМ<sup class=\"fn\">502</sup>"],["n",[[502,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Нечто подобное приходит в слабых хадисах. Например, в хадисе со слов Джабира пришло: </i><b><i>\"Облачайте ваших покойных в красивые саваны, ведь они навещают друг друга в могилах и хвалятся ими друг перед другом\". </i></b><i>Передал ад-Дейлями, но среди его передатчиков есть целая группа тех, кого я не знаю. Есть еще два других похожих хадиса. Их упомянул Ибн уль-Джаузи в \"аль-Мауду′ат\"». </i>"]]],["p","<b>См. «аль-Мадхаль», 3/277; «Ахкам аль-джанаиз», стр. 312; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""]]];
